window.kbPageData["views/entry/k-153c5d3d04ac27f2"] = {"key":"entry/k-153c5d3d04ac27f2","state":{"route":"entry/k-153c5d3d04ac27f2"},"node":{"id":"k-153c5d3d04ac27f2","mode":"k","title":"赤字率","type":"概念与词义","domain":"统计","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["finance"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["经济","统计"],"来源主题":["经济指标与宏观调控"],"资料类别":["非时政"]},"supplement":[{"doc":"6cbfb01fe723bba64b75","file":"《2026年政府工作报告》粉笔解读.pdf","first":23,"last":23,"relation":"辨析","evidenceId":"aca89578afb850bad005","cardId":"565171d1d657d930","questionId":null,"basis":"机构注释","quote":"2.赤字率财政赤字率，是指财政赤字与同期国内生产总值（GDP）的比例。","text":"赤字率等于财政赤字与同期 GDP 之比。例如 GDP 从 100 增至 110，赤字率均为 4%，对应的赤字规模从 4 增至 4.4。","reference":null}],"directorySummary":"赤字率等于财政赤字与同期 GDP 之比。例如 GDP 从 100 增至 110，赤字率均为 4%，对应的赤字规模从 4 增至 4.4。","sources":[{"id":"565171d1d657d930","label":"赤字率","topic":"经济指标与宏观调控","category":"非时政","text":"2.赤字率\n财政赤字率，是指财政赤字与同期国内生产总值（GDP）的比例。从近年我国赤字率安\n排来看，2024 年为 3%，2025 年提高到 4%左右，今年继续按 4%左右安排。\n赤字率延续 4%左右，是历史上比较高的水平，体现了今年财政政策继续更加积极的取\n向。虽然今年赤字率和去年一样，但由于 GDP 这个分母变大了，所以今年赤字规模比上年增\n加 2300 亿元。","source":{"doc":"6cbfb01fe723bba64b75","first":23,"last":23,"page":23,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-153c5d3d04ac27f2":[]}};
